/// <summary>
/// The <c>METCustFreeInvoiceForm_Extension</c> class manages enabled or disable the workflow button.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(formStr(CustFreeInvoice))]
public final class METCustFreeInvoiceForm_Extension
{
}

Method.Source:
/// <summary>
/// Enable or disable the button based on workflow user exclusion list.
/// </summary>
void allowedit()
{
    next allowedit();

    if (METBulkWFFreeTextInvoiceHelper::checkUserIdIsPartofExclusionlist())
    {
        custInvoiceTable_ds.allowEdit(true);
        custInvoiceLine_ds.allowEdit(true);

        custInvoiceTable_ds.object(fieldNum(CustInvoiceTable, PostalAddress)).allowEdit(true);

        buttonSetupPaymFormat.enabled(true);
        tradeBLWIChangeCode.enabled(true);
        custOpenTransButton.enabled(true);

        newInvoiceLine.enabled(true);
        deleteInvoiceLine.enabled(true);
        copyLinesDropDialog.enabled(true);
    }
}
